 10→interface MemoriesPanelProps {
 11→  refreshKey: number;
 12→}
 13→
 14→const CATEGORY_ORDER: MemoryEntry['category'][] = ['preference', 'fact', 'pattern'];
 15→
 16→const CATEGORY_I18N: Record<MemoryEntry['category'], string> = {
 17→  preference: 'preferencesCategory',
 18→  fact: 'factsCategory',
 19→  pattern: 'patternsCategory',
 20→};
 21→
 22→const CATEGORY_EMPTY_I18N: Record<MemoryEntry['category'], string> = {
 23→  preference: 'noPreferences',
 24→  fact: 'noFacts',
 25→  pattern: 'noPatterns',
 26→};
 27→
 28→export function MemoriesPanel({ refreshKey }: MemoriesPanelProps) {
 29→  const { t } = useTranslation();
 30→  const [entries, setEntries] = useState<MemoryEntry[]>([]);
 31→  const [rawContent, setRawContent] = useState('');
 32→  const [showFileModal, setShowFileModal] = useState(false);
 33→  const [detailTab, setDetailTab] = useState<'preview' | 'source'>('preview');
 34→
 35→  const loadMemories = useCallback(async () => {
 36→    try {
 37→      const data = await fetchMemories();
 38→      setEntries(data.entries);
 39→      setRawContent(data.raw);
 40→    } catch {
 41→      // silently ignore
 42→    }
 43→  }, []);
 44→
 45→  useEffect(() => { loadMemories(); }, [loadMemories, refreshKey]);
 46→
 47→  useEffect(() => {
 48→    const handler = () => loadMemories();
 49→    window.addEventListener('memories-updated', handler);
 50→    return () => window.removeEventListener('memories-updated', handler);
 51→  }, [loadMemories]);
 52→
 53→  const handleDelete = async (content: string) => {
 54→    if (!confirm(t('deleteMemoryConfirm'))) return;
 55→    try {
 56→      await apiDeleteMemory(content);
 57→      await loadMemories();
 58→    } catch {
 59→      // silently ignore
 60→    }
 61→  };
 62→
 63→  const handleViewFile = () => {
 64→    setDetailTab('preview');
 65→    setShowFileModal(true);
 66→  };
 67→
 68→  const grouped = CATEGORY_ORDER
 69→    .map((cat) => ({ category: cat, items: entries.filter((e) => e.category === cat) }));
 70→
 71→  return (
 72→    <div className="memories-panel">
 73→      <div className="memories-panel__actions">
 74→        <button
 75→          className="memories-panel__action-btn"
 76→          onClick={handleViewFile}
 77→          title={t('viewMemoryFile')}
 78→          aria-label={t('viewMemoryFile')}
 79→        >
 80→          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg>
 81→        </button>
 82→      </div>
 83→      {grouped.map((group) => (
 84→        <div key={group.category} className="memories-panel__section">
 85→          <h3 className="memories-panel__section-title">{t(CATEGORY_I18N[group.category])}</h3>
 86→          {group.items.length === 0 ? (
