 95→                    onClick={() => handleDelete(entry.content)}
 96→                    title={t('deleteMemory')}
 97→                  >
 98→                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
 99→                  </button>
100→                </li>
101→              ))}
102→            </ul>
103→          )}
104→        </div>
105→      ))}
106→
107→      {showFileModal && createPortal(
108→        <div className="skill-detail-overlay" onClick={() => setShowFileModal(false)}>
109→          <div className="skill-detail-modal" onClick={(e) => e.stopPropagation()}>
110→            <div className="skill-detail-modal__header">
111→              <span className="skill-detail-modal__name">{t('memoryFileTitle')}</span>
112→              <button className="skill-detail-modal__close" onClick={() => setShowFileModal(false)}>
113→                &times;
114→              </button>
115→            </div>
116→            <div className="skill-detail-modal__tabs">
117→              <button
118→                className={`skill-detail-modal__tab${detailTab === 'preview' ? ' skill-detail-modal__tab--active' : ''}`}
119→                onClick={() => setDetailTab('preview')}
120→              >
121→                {t('memoryPreview')}
122→              </button>
123→              <button
124→                className={`skill-detail-modal__tab${detailTab === 'source' ? ' skill-detail-modal__tab--active' : ''}`}
125→                onClick={() => setDetailTab('source')}
126→              >
127→                {t('memorySource')}
128→              </button>
129→            </div>
130→            {detailTab === 'preview' ? (
131→              <div className="skill-detail-modal__content skill-detail-modal__content--preview">
132→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{rawContent || '*No content*'}</ReactMarkdown>
133→              </div>
134→            ) : (
135→              <pre className="skill-detail-modal__content">{rawContent || ''}</pre>
136→            )}
137→          </div>
138→        </div>,
139→        document.body
140→      )}
141→    </div>
142→  );
143→}
